import 'package:flutter_test/flutter_test.dart';import 'package:surge_wizard/core/dungeon_run_state_v4.dart';import 'package:surge_wizard/core/vertical_slice_catalog_v4.dart';void main(){test('carry copy is deep and preserves retry safe state',(){final w=VerticalSliceCatalogV4.wizard();final o=DungeonCarryStateV4.fromParty([w],hpPotions:2);o.party['wizard']!.startBarrier=10;final c=o.copy();c.party['wizard']!.hp=1;c.hpPotions=0;expect(o.party['wizard']!.hp,w.stats.maxHp);expect(o.hpPotions,2);});}
